def p(text): return {'type': 'p', 'text': text}
def h(text): return {'type': 'h3', 'text': text}
def table(caption, headers, rows, widths=None):
    return {'type': 'table', 'caption': caption, 'headers': headers, 'rows': rows, 'widths': widths}
def figure(file, caption, alt): return {'type': 'figure', 'file': file, 'caption': caption, 'alt': alt}
def section(id, title, *blocks): return {'id': id, 'title': title, 'blocks': list(blocks)}

