def markdown_sections(sections, include_figures=True):
    lines=[]
    for sec in sections:
        lines += ['## '+sec['title'], '']
        for b in sec['blocks']:
            if b['type']=='p': lines += [b['text'], '']
            elif b['type']=='h3': lines += ['### '+b['text'], '']
            elif b['type']=='list': lines += [f'{i}. {t}' for i,t in enumerate(b['items'],1)]+['']
            elif b['type']=='table':
                lines += [b['caption'], '', '| '+' | '.join(b['headers'])+' |', '| '+' | '.join(['---']*len(b['headers']))+' |']
                lines += ['| '+' | '.join(map(str,r))+' |' for r in b['rows']]+['']
            elif b['type']=='figure' and include_figures:
                lines += [f'![{b["alt"]}](../outputs/public/{b["file"]})', '', b['caption'], '']
    return '\n'.join(lines)

if __name__=='__main__':
    content='# '+TITLE+'\n\n'+SUBTITLE+'\n\n'+AUTHOR+' · University of Pennsylvania · '+DATE+'\n\n'
    content+=markdown_sections(get_sections())+'\n## References\n\n'
    content+='\n\n'.join(f'{i}. {label} [Source]({url})' for i,(label,url) in enumerate(REFERENCES,1))+'\n'
    (ROOT/'docs/study_report.md').write_text(content)
    print('Wrote docs/study_report.md')
